// Minimal hand-rolled service worker — not generated by a bundler plugin, so
// it works the same under Turbopack or webpack. Deliberately does NOT cache
// pages or API responses: this app is auth-gated and highly dynamic
// (per-user data, live pricing, messages), so caching that would risk
// serving stale or cross-user content. It only exists to (a) satisfy
// Chrome's installability check (wants a registered service worker with a
// fetch handler) and (b) cache-first the few genuinely static assets so the
// app shell's icons/manifest still resolve offline.
const CACHE_NAME = "rentrospect-static-v1";
const STATIC_ASSETS = [
  "/manifest.webmanifest",
  "/icon-192x192.png",
  "/icon-512x512.png",
  "/apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(STATIC_ASSETS))
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)))
    )
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only ever intercept the exact static assets above — everything else
  // (pages, API calls, images, fonts) goes straight to the network
  // untouched.
  const url = new URL(request.url);
  if (request.method !== "GET" || !STATIC_ASSETS.includes(url.pathname)) {
    return;
  }

  event.respondWith(
    caches.match(request).then((cached) => cached ?? fetch(request))
  );
});
